  1→//go:build linux || darwin
  2→
  3→package vfs
  4→
  5→// xattr_unix.go —— 扩展属性访问器。
  6→//
  7→// 用途（阶段二）：macOS 的 Finder 元数据与资源叉最终要落到这里 ——
  8→// `com.apple.FinderInfo`（= SMB 的 AFP_AfpInfo 流）、
  9→// `com.apple.ResourceFork`（= AFP_Resource 流）、`com.apple.metadata:*`。
 10→// Samba 的 vfs_fruit 就是这么干的，macOS 客户端也是这么期待的。
 11→//
 12→// 命名空间差异：
 13→//   - Linux 的非特权进程只能读写 `user.` 命名空间，其余会 EPERM，
 14→//     所以没有已知前缀的名字一律加上 `user.`，读回时再剥掉；
 15→//   - macOS 没有命名空间概念，原样使用。
 16→//
 17→// 这个差异必须双向对称，否则 List() 报出来的名字客户端拿去 Get 会找不到。
 18→
 19→import (
 20→	"os"
 21→	"runtime"
 22→	"strings"
 23→
 24→	"golang.org/x/sys/unix"
 25→)
 26→
 27→// xattrNeedsUserPrefix 只有 Linux 为 true。
 28→var xattrNeedsUserPrefix = runtime.GOOS == "linux"
 29→
 30→// linuxNamespaces 是 Linux 内核认可的扩展属性命名空间前缀。
 31→var linuxNamespaces = []string{"user.", "trusted.", "security.", "system."}
 32→
 33→type unixXattr struct {
 34→	path string
 35→	// fd 为 -1 表示只能按路径访问（OpenAttrOnly 句柄）。
 36→	fd int
 37→}
 38→
 39→// newXattrAccessor 构造扩展属性访问器。
 40→func newXattrAccessor(path string, f *os.File) (XattrAccessor, error) {
 41→	x := &unixXattr{path: path, fd: -1}
 42→	if f != nil {
 43→		x.fd = int(f.Fd())
 44→	}
 45→	return x, nil
 46→}
 47→
 48→// encodeName 把 SMB 侧的名字映射成宿主机的扩展属性名。
 49→func encodeName(name string) string {
 50→	if !xattrNeedsUserPrefix {
 51→		return name
 52→	}
 53→	for _, ns := range linuxNamespaces {
 54→		if strings.HasPrefix(name, ns) {
 55→			return name
 56→		}
 57→	}
 58→	return "user." + name
 59→}
 60→
 61→// decodeName 是 encodeName 的逆操作。
 62→func decodeName(raw string) string {
 63→	if !xattrNeedsUserPrefix {
 64→		return raw
 65→	}
 66→	return strings.TrimPrefix(raw, "user.")
 67→}
 68→
 69→func (x *unixXattr) Get(name string) ([]byte, error) {
 70→	n := encodeName(name)
 71→	// 两趟：先问长度再分配。不能一次性开个大 buffer 了事 ——
 72→	// 资源叉可以有几十 MB，猜大了浪费、猜小了 ERANGE。
 73→	size, err := x.get(n, nil)
 74→	if err != nil {
 75→		return nil, mapXattrError(err)
 76→	}
 77→	if size == 0 {
 78→		return []byte{}, nil
 79→	}
 80→	buf := make([]byte, size)
 81→	got, err := x.get(n, buf)
 82→	if err != nil {
 83→		return nil, mapXattrError(err)
 84→	}
 85→	if got > len(buf) {
 86→		// 两趟之间被别人写大了，防御性截断而不是越界。
 87→		got = len(buf)
 88→	}
 89→	return buf[:got], nil
 90→}
 91→
 92→func (x *unixXattr) get(name string, dest []byte) (int, error) {
 93→	if x.fd >= 0 {
 94→		return unix.Fgetxattr(x.fd, name, dest)
 95→	}
 96→	return unix.Getxattr(x.path, name, dest)
 97→}
 98→
 99→func (x *unixXattr) Set(name string, value []byte) error {
100→	n := encodeName(name)
101→	var err error
102→	if x.fd >= 0 {
103→		err = unix.Fsetxattr(x.fd, n, value, 0)
104→	} else {
105→		err = unix.Setxattr(x.path, n, value, 0)
106→	}
107→	return mapXattrError(err)
108→}
109→
110→func (x *unixXattr) Remove(name string) error {
111→	n := encodeName(name)
112→	var err error
113→	if x.fd >= 0 {
114→		err = unix.Fremovexattr(x.fd, n)
115→	} else {
116→		err = unix.Removexattr(x.path, n)
117→	}
118→	return mapXattrError(err)
119→}
120→
121→func (x *unixXattr) List() ([]string, error) {
122→	size, err := x.list(nil)
123→	if err != nil {
124→		return nil, mapXattrError(err)
125→	}
126→	if size == 0 {
127→		return nil, nil
128→	}
129→	buf := make([]byte, size)
130→	got, err := x.list(buf)
131→	if err != nil {
132→		return nil, mapXattrError(err)
133→	}
134→	if got > len(buf) {
135→		got = len(buf)
136→	}
137→	// 返回值是一串 NUL 结尾的名字拼接而成。
138→	out := make([]string, 0, 8)
139→	for _, raw := range strings.Split(string(buf[:got]), "\x00") {
140→		if raw == "" {
141→			continue
142→		}
143→		out = append(out, decodeName(raw))
144→	}
145→	return out, nil
146→}
147→
148→func (x *unixXattr) list(dest []byte) (int, error) {
149→	if x.fd >= 0 {
150→		return unix.Flistxattr(x.fd, dest)
151→	}
152→	return unix.Listxattr(x.path, dest)
153→}
154→
155→// mapXattrError 在通用 errmap 之上补两条扩展属性特有的语义。
156→func mapXattrError(err error) error {
157→	if err == nil {
158→		return nil
159→	}
160→	if err == errnoNoAttr {
161→		// 「这个属性不存在」，对客户端而言等价于对象不存在。
162→		// Linux 用 ENODATA，macOS 用 ENOATTR，常量在 sys_{linux,darwin}.go。
163→		return ErrNotFound
164→	}
165→	switch err {
166→	case unix.ENOTSUP:
167→		// 文件系统没开 user_xattr（老 ext3、某些 tmpfs 配置）。
168→		return ErrNotSupported
169→	}
170→	return mapError(err)
171→}
