		probeRsrc := true
		if snapped {
			_, probeRsrc = dotUnder[name]
		}
		// 直接拼接而不是 filepath.Join：name 已经过 validateChildName，
		// 不含分隔符也不是 "."/“..”，无需再走一遍 Clean。
		out[i].FinderInfo, out[i].RsrcSize, out[i].Err =
			h.fs.appleInfoAt(prefix+name, probeRsrc, scratch)
	}
	return out, nil
