import (
	"bytes"
	"errors"
	"io"
	"testing"
)

// seedAppleDir 造一个混合目录：有元数据的、没元数据的、只有资源派生的。
func seedAppleDir(t *testing.T, fs *LocalFS) []string {
	t.Helper()

	writeFile(t, fs, "plain1", "a")
	writeFile(t, fs, "plain2", "bb")
	writeFile(t, fs, "withfi", "c")
