  2→
  3→package vfs
  4→
  5→// xattr_unix.go —— 扩展属性访问器。
  6→//
  7→// 用途（阶段二）：macOS 的 Finder 元数据与资源叉最终要落到这里 ——
  8→// `com.apple.FinderInfo`（= SMB 的 AFP_AfpInfo 流）、
  9→// `com.apple.ResourceFork`（= AFP_Resource 流）、`com.apple.metadata:*`。
 10→// Samba 的 vfs_fruit 就是这么干的，macOS 客户端也是这么期待的。
 11→//
 12→// 命名空间差异：
 13→//   - Linux 的非特权进程只能读写 `user.` 命名空间，其余会 EPERM，
 14→//     所以没有已知前缀的名字一律加上 `user.`，读回时再剥掉；
 15→//   - macOS 没有命名空间概念，原样使用。
 16→//
 17→// 这个差异必须双向对称，否则 List() 报出来的名字客户端拿去 Get 会找不到。
 18→
 19→import (
 20→	"os"
 21→	"runtime"
 22→	"strings"
 23→
 24→	"golang.org/x/sys/unix"
 25→)
 26→
 27→// xattrNeedsUserPrefix 只有 Linux 为 true。
 28→var xattrNeedsUserPrefix = runtime.GOOS == "linux"
 29→
 30→// linuxNamespaces 是 Linux 内核认可的扩展属性命名空间前缀。
 31→var linuxNamespaces = []string{"user.", "trusted.", "security.", "system."}
 32→
 33→type unixXattr struct {
 34→	path string
 35→	// fd 为 -1 表示只能按路径访问（OpenAttrOnly 句柄）。
 36→	fd int
 37→}
 38→
 39→// newXattrAccessor 构造扩展属性访问器。
 40→func newXattrAccessor(path string, f *os.File) (XattrAccessor, error) {
 41→	x := &unixXattr{path: path, fd: -1}
 42→	if f != nil {
 43→		x.fd = int(f.Fd())
 44→	}
 45→	return x, nil
 46→}
 47→
 48→// encodeName 把 SMB 侧的名字映射成宿主机的扩展属性名。
 49→func encodeName(name string) string {
 50→	if !xattrNeedsUserPrefix {
 51→		return name
 52→	}
 53→	for _, ns := range linuxNamespaces {
 54→		if strings.HasPrefix(name, ns) {
 55→			return name
 56→		}
 57→	}
 58→	return "user." + name
 59→}
 60→
 61→// decodeName 是 encodeName 的逆操作。
 62→func decodeName(raw string) string {
 63→	if !xattrNeedsUserPrefix {
 64→		return raw
 65→	}
 66→	return strings.TrimPrefix(raw, "user.")
 67→}
 68→
 69→func (x *unixXattr) Get(name string) ([]byte, error) {
 70→	n := encodeName(name)
 71→	// 两趟：先问长度再分配。不能一次性开个大 buffer 了事 ——
 72→	// 资源叉可以有几十 MB，猜大了浪费、猜小了 ERANGE。
 73→	size, err := x.get(n, nil)
 74→	if err != nil {
 75→		return nil, mapXattrError(err)
 76→	}
 77→	if size == 0 {
 78→		return []byte{}, nil
 79→	}
 80→	buf := make([]byte, size)
 81→	got, err := x.get(n, buf)
 82→	if err != nil {
 83→		return nil, mapXattrError(err)
 84→	}
 85→	if got > len(buf) {
 86→		// 两趟之间被别人写大了，防御性截断而不是越界。
 87→		got = len(buf)
 88→	}
 89→	return buf[:got], nil
 90→}
 91→
 92→func (x *unixXattr) get(name string, dest []byte) (int, error) {
 93→	if x.fd >= 0 {
 94→		return unix.Fgetxattr(x.fd, name, dest)
 95→	}
 96→	return unix.Getxattr(x.path, name, dest)
 97→}
 98→
 99→// netatalkMetaHostName 是 netatalkMetaXattr 在宿主机上的名字
100→// （Linux 上带 "user." 前缀）。encodeName 每次调用都要拼一次字符串，
101→// 而 readdir_attr 是每条目录项调一次的热路径，这里算一次存下来。
102→var netatalkMetaHostName = encodeName(netatalkMetaXattr)
103→
104→// readMetaXattrFast 用**一次** getxattr 把 netatalk metadata blob 读进 scratch。
105→//
106→// 与 XattrAccessor.Get 的区别：Get 是通用接口，必须先问长度再分配
107→// （资源叉可以有几十 MB）。但 metadata blob 的长度是规范固定的
108→// 402 字节（AD_DATASZ_XATTR），可以直接开一个够用的缓冲一趟读完 ——
109→// 在 readdir_attr 的十万级目录上省掉的是「一次 syscall + 一次分配」× 条目数。
110→//
111→// 返回的切片指向 scratch，**下一次调用会覆盖它**，调用方必须在返回前用完。
112→// 属性不存在时返回 ErrNotFound（对应「这个对象没有 FinderInfo」）。
113→func readMetaXattrFast(host string, scratch []byte) ([]byte, error) {
114→	if cap(scratch) < adMetaSize {
115→		scratch = make([]byte, adMetaSize)
116→	}
117→	dest := scratch[:adMetaSize]
118→
119→	n, err := unix.Getxattr(host, netatalkMetaHostName, dest)
120→	if err != nil {
121→		if err == unix.ERANGE {
122→			// blob 比 402 大 —— 规范外的写入者（未来版本的 Netatalk、
123→			// 或别的实现塞了额外 entry）。退回两趟读法而不是报错。
124→			x, xerr := newXattrAccessor(host, nil)
125→			if xerr != nil {
126→				return nil, xerr
127→			}
128→			return x.Get(netatalkMetaXattr)
129→		}
130→		return nil, mapXattrError(err)
131→	}
132→	if n > len(dest) {
133→		// 内核不应返回超过 len(dest) 的值；防御性截断而不是越界切片。
134→		n = len(dest)
135→	}
136→	return dest[:n], nil
137→}
138→
139→func (x *unixXattr) Set(name string, value []byte) error {
140→	n := encodeName(name)
141→	var err error
142→	if x.fd >= 0 {
143→		err = unix.Fsetxattr(x.fd, n, value, 0)
144→	} else {
145→		err = unix.Setxattr(x.path, n, value, 0)
146→	}
147→	return mapXattrError(err)
148→}
149→
150→func (x *unixXattr) Remove(name string) error {
151→	n := encodeName(name)
152→	var err error
153→	if x.fd >= 0 {
154→		err = unix.Fremovexattr(x.fd, n)
155→	} else {
156→		err = unix.Removexattr(x.path, n)
157→	}
158→	return mapXattrError(err)
159→}
160→
161→func (x *unixXattr) List() ([]string, error) {
162→	size, err := x.list(nil)
163→	if err != nil {
164→		return nil, mapXattrError(err)
165→	}
166→	if size == 0 {
167→		return nil, nil
168→	}
169→	buf := make([]byte, size)
170→	got, err := x.list(buf)
171→	if err != nil {
172→		return nil, mapXattrError(err)
173→	}
174→	if got > len(buf) {
175→		got = len(buf)
176→	}
177→	// 返回值是一串 NUL 结尾的名字拼接而成。
178→	out := make([]string, 0, 8)
179→	for _, raw := range strings.Split(string(buf[:got]), "\x00") {
180→		if raw == "" {
181→			continue
182→		}
183→		out = append(out, decodeName(raw))
184→	}
185→	return out, nil
186→}
187→
188→func (x *unixXattr) list(dest []byte) (int, error) {
189→	if x.fd >= 0 {
190→		return unix.Flistxattr(x.fd, dest)
191→	}
192→	return unix.Listxattr(x.path, dest)
193→}
194→
195→// mapXattrError 在通用 errmap 之上补两条扩展属性特有的语义。
196→func mapXattrError(err error) error {
197→	if err == nil {
198→		return nil
199→	}
200→	if err == errnoNoAttr {
201→		// 「这个属性不存在」，对客户端而言等价于对象不存在。
202→		// Linux 用 ENODATA，macOS 用 ENOATTR，常量在 sys_{linux,darwin}.go。
203→		return ErrNotFound
204→	}
205→	switch err {
206→	case unix.ENOTSUP:
207→		// 文件系统没开 user_xattr（老 ext3、某些 tmpfs 配置）。
208→		return ErrNotSupported
209→	}
210→	return mapError(err)
211→}
