func (h *streamHandle) flushLocked() error {
	if h.kind == streamKindResource || !h.dirty {
		return nil
	}

	if h.kind == streamKindXattr {
		if err := h.fs.writeDosStream(h.host, h.slot, h.buf); err != nil {
