		// 磁盘上的旧值。SMB2 FLUSH 能承载这个错误，CLOSE 不能。
		return ErrBadAfpInfo
	}
	if err := h.fs.writeAfpInfo(h.host, ai); err != nil {
		return err
	}
	h.dirty = false
	return nil
